"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[538],{11468:e=>{e.exports=JSON.parse('{"functions":[{"name":"Score","desc":"Score `holder` as a destination for `config`.\\n\\nA holder with an `Accepts` predicate is the Inventory2 spelling of\\nFilteredInventorySlot: matching earns the Filter tier, failing excludes it.\\nReturns `None` for any holder the item cannot go in at all.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":65,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/SlotPriority.luau"}},{"name":"IsUsable","desc":"Whether a score means \\"usable at all\\".\\n\\nThe old code compared against FillPriority.Last rather than zero, so a slot\\ncould be deprioritised below every other slot without being excluded. Kept.","params":[{"name":"score","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":98,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/SlotPriority.luau"}},{"name":"Rank","desc":"","params":[{"name":"holders","desc":"","lua_type":"{ ItemHolder }"},{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"{ Ranked }\\n"}],"function_type":"method","source":{"line":118,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/SlotPriority.luau"}}],"properties":[],"types":[],"name":"SlotPriority","desc":"Which slot an item should go in.\\n\\nThis is the one thing InventoryController did that Inventory2 did not. Its\\nscoring machinery looked elaborate -- FillPriority spanning -inf to +inf,\\nGetItemScore, GetSpaceInSlot returning a score alongside the space,\\nGetSlotSpaceForItem sorting on it -- but InventorySlot:GetItemScore returns a\\nconstant 1, so for an ordinary slot the whole thing collapses to:\\n\\n    same item first, then empty, lower index wins.\\n\\nWhich is exactly what HolderService.TransferToGroup already does with its two\\npasses. The part that does NOT collapse is FilteredInventorySlot: it overrides\\nGetItemScore to return FillPriority.Filter (5000) when its filters match and\\nFillPriority.None (-inf) when they do not. Since the score is ADDITIVE with\\nthe Empty/Similar modifier, a matching filtered slot outranks everything --\\nan ammo pouch fills before an existing ammo stack elsewhere in the bag.\\n\\nThat ordering is what this module preserves. The tiers are kept at their\\noriginal values so the two implementations can be compared numerically.","source":{"line":26,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/SlotPriority.luau"}}')}}]);